def apply_track(ctx, clip):
    """core track type 'filter': clip = {start, dur, filter, intensity}"""
    r = ctx.resolve(clip.get("filter"))
    if r:
        ctx.ensure_track("filter")
        ctx.script.add_filter(ctx.enum(r), ctx.timerange(clip), ctx.track_name,
                              intensity=float(clip.get("intensity", 100)))

