python.background:
JIANYING = {
    "bg_color": {"api": "add_background_filling", "type": "color", "v4_confirmed": False},
    "bg_blur": {"api": "add_background_filling", "type": "blur", "v4_confirmed": True},
}


def apply(ctx, seg, bg, clip):
    if bg.get("type") == "blur":
        if ctx.resolve("bg_blur"):
            seg.add_background_filling("blur", float(bg.get("value") or 0.0625))
    elif ctx.resolve("bg_color"):
        seg.add_background_filling("color", color=str(bg.get("value") or "#000000FF"))

